```python
import sys


def main():
    data = sys.stdin.read().split('\n')
    pos = 0

    def readline():
        nonlocal pos
        if pos < len(data):
            line = data[pos]
            pos += 1
            return line.strip()
        return None

    first = readline()
    while first is not None and first == '':
        first = readline()
    if first is None:
        sys.stdout.write("ERR\n")
        return
    try:
        k = int(first)
    except ValueError:
        sys.stdout.write("ERR\n")
        return

    prog = []
    for _ in range(k):
        raw = readline()
        fields = ("" if raw is None else raw).split()
        op = fields[0].upper() if fields else "BAD"
        arg = None
        if op in ("PUSH", "JNZ"):
            if len(fields) == 2:
                try:
                    arg = int(fields[1])
                except ValueError:
                    op = "BAD"
            else:
                op = "BAD"
        elif op in ("POP", "ADD", "SUB", "MUL", "DUP", "SWAP", "PRINT", "HALT"):
            if len(fields) != 1:
                op = "BAD"
        else:
            op = "BAD"
        prog.append((op, arg))

    stack = []
    printed = []
    pc = 0
    steps = 0
    err = False

    while True:
        if steps >= 10000 or pc < 0 or pc >= len(prog):
            err = True
            break
        steps += 1
        op, arg = prog[pc]
        nxt = pc + 1
        if op == "PUSH":
            stack.append(arg)
        elif op == "POP":
            if not stack:
                err = True
                break
            stack.pop()
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                err = True
                break
            a = stack.pop()
            b = stack.pop()
            if op == "ADD":
                stack.append(b + a)
            elif op == "SUB":
                stack.append(b - a)
            else:
                stack.append(b * a)
        elif op == "DUP":
            if not stack:
                err = True
                break
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                err = True
                break
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "PRINT":
            if not stack:
                err = True
                break
            printed.append(str(stack.pop()))
        elif op == "JNZ":
            if not stack:
                err = True
                break
            value = stack.pop()
            if value != 0:
                if arg is None or arg < 0 or arg >= len(prog):
                    err = True
                    break
                nxt = arg
        elif op == "HALT":
            if printed:
                sys.stdout.write('\n'.join(printed) + '\n')
            return
        else:
            err = True
            break
        pc = nxt

    if err:
        sys.stdout.write("ERR\n")


main()
```

Key details: `SUB` computes `b - a` (second-from-top minus top), `JNZ` pops before jumping and validates the target, and stepping off the end of the program or never reaching `HALT` within 10000 steps prints `ERR`.
